'use strict';
(()=>{const panels={portal:'portalPanel',home:'homePanel',form:'capture',saved:'review',status:'tracker',admin:'adminPanel',profile:'profilePanel',settings:'settingsPanel',import:'importPanel',changelog:'changelogPanel'},buttons={portal:'portalHomeTab',form:'liveTab',saved:'savedTab',status:'statusTab',admin:'adminTab',profile:'profileTab',settings:'settingsTab',import:'importTab',changelog:'changelogTab',home:'homeTab'};let api,armed=false,restoring=false;const $=id=>document.getElementById(id),key=()=> 'guhuza.navigation.v1.'+api.user().id;function read(){try{return JSON.parse(sessionStorage.getItem(key())||'null');}catch{return null;}}
function save(){if(!armed||restoring||!api?.user()||window.GuhuzaActAs?.isChild||$('workspace').hidden)return;const page=Object.keys(panels).find(p=>$(panels[p])&&!$(panels[p]).hidden);if(!page)return;const state={page,portalVersion:3};if(page==='portal')state.portal=GuhuzaTeams.navigationState();if(page==='saved'){state.interview=legacy.navigationState();state.library=GuhuzaLibrary.navigationState();}if(page==='status')state.library=GuhuzaLibrary.navigationState();if(page==='admin'){state.admin=GuhuzaAdmin.navigationState();}try{sessionStorage.setItem(key(),JSON.stringify(state));}catch{}}
async function restore(){armed=false;restoring=true;const state=read();try{if(!state?.portalVersion){GuhuzaTeams.home();return;}if(state.page==='portal'){await GuhuzaTeams.restoreNavigation(state.portal);return;}if(!state||!Object.hasOwn(panels,state.page)||window.GuhuzaActAs?.isChild){GuhuzaTeams.home();return;}if(state.page==='admin'){if(!api.profile()?.is_admin){GuhuzaUI.show('home');return;}await GuhuzaAdmin.restoreNavigation(state.admin||{});return;}if(state.page==='saved'&&state.interview?.id&&!state.interview.browse){const record=legacy.records().find(r=>r.id===state.interview.id),owns=record&&window.GuhuzaRecordAccess.owns(record.id),team=state.interview.scope==='team'&&window.GuhuzaRecordAccess.canViewAll();if(record&&(owns||team)){if(team)legacy.openTeam(record.id);else legacy.open(record.id);return;}}$(buttons[state.page])?.click();if(state.page==='saved'||state.page==='status')GuhuzaLibrary.restoreNavigation(state.library||{});if(state.page==='changelog')GuhuzaChanges.render();}catch{GuhuzaTeams.home();}finally{restoring=false;armed=true;save();}}
window.GuhuzaNavigation={start(context){api=context;for(const event of ['click','input','change'])document.addEventListener(event,()=>queueMicrotask(save));window.addEventListener('pagehide',save);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save();});},restore,save,stop(){armed=false;}};
})();
